contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address u) public payable {
        uint256 first = c.getBalance(u); if (__ESBMC_reverted()) return;
        uint256 second = c.getBalance(u); if (__ESBMC_reverted()) return;
        assert(first == second);
    }

    receive() external payable {}
}

